import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    nums = list(map(int, data[1:1 + n])) if n > 0 else []
    if n == 0:
        avg = 0.0
    else:
        avg = sum(nums) / n
    # Ensure floating point representation (e.g., 20.0 instead of 20)
    if avg == int(avg):
        print(f"{avg:.1f}")
    else:
        print(avg)

if __name__ == "__main__":
    solve()
